import { test, expect } from '@playwright/test';

test.describe('Search Results Filtering by Category', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should filter search results by selecting category checkboxes', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search products...');
    await expect(searchInput).toBeVisible();

    // Perform search
    await searchInput.fill('laptop');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Verify search results are displayed
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.getByTestId('result-item');
    await expect(resultItems).toHaveCount(10);

    // Verify category filter section is visible
    const filterSection = page.getByTestId('category-filter');
    await expect(filterSection).toBeVisible();

    // Select 'Electronics' category checkbox
    const electronicsCheckbox = page.getByLabel('Electronics');
    await expect(electronicsCheckbox).toBeVisible();
    await electronicsCheckbox.click();

    // Verify 'Electronics' checkbox is checked
    await expect(electronicsCheckbox).toBeChecked();

    // Verify search results are filtered
    await expect(resultItems).toHaveCount(5);
    const filteredResult = page.getByTestId('result-item').first();
    await expect(filteredResult).toContainText('laptop');

    // Verify filter applied message
    const filterAppliedMessage = page.getByText('Showing 5 results in Electronics');
    await expect(filterAppliedMessage).toBeVisible();

    // Deselect 'Electronics' category checkbox
    await electronicsCheckbox.click();
    await expect(electronicsCheckbox).not.toBeChecked();

    // Verify all results are shown again
    await expect(resultItems).toHaveCount(10);
    await expect(filterAppliedMessage).not.toBeVisible();
  });

  test('should handle multiple category selections and clear filters', async ({ page }) => {
    // Perform initial search
    const searchInput = page.getByPlaceholder('Search products...');
    await searchInput.fill('phone');
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Verify initial results
    const resultItems = page.getByTestId('result-item');
    await expect(resultItems).toHaveCount(10);

    // Select 'Electronics' category
    const electronicsCheckbox = page.getByLabel('Electronics');
    await electronicsCheckbox.click();
    await expect(electronicsCheckbox).toBeChecked();

    // Select 'Accessories' category
    const accessoriesCheckbox = page.getByLabel('Accessories');
    await accessoriesCheckbox.click();
    await expect(accessoriesCheckbox).toBeChecked();

    // Verify results are filtered by both categories
    await expect(resultItems).toHaveCount(7);
    const filterAppliedMessage = page.getByText('Showing 7 results in Electronics and Accessories');
    await expect(filterAppliedMessage).toBeVisible();

    // Verify both categories are selected
    await expect(electronicsCheckbox).toBeChecked();
    await expect(accessoriesCheckbox).toBeChecked();

    // Clear all filters button
    const clearFiltersButton = page.getByRole('button', { name: /clear filters/i });
    await clearFiltersButton.click();

    // Verify all checkboxes are unchecked
    await expect(electronicsCheckbox).not.toBeChecked();
    await expect(accessoriesCheckbox).not.toBeChecked();

    // Verify all results are displayed again
    await expect(resultItems).toHaveCount(10);
    await expect(filterAppliedMessage).not.toBeVisible();
  });
});
